PRAGMA defer_foreign_keys = ON;
CREATE TABLE papers_new (id TEXT PRIMARY KEY, center_id TEXT NOT NULL, exam_id TEXT NOT NULL, subject_id TEXT NOT NULL, maximum INTEGER NOT NULL CHECK(maximum>0 AND maximum<=999999999), position INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, UNIQUE(center_id,id), UNIQUE(center_id,exam_id,subject_id), FOREIGN KEY(center_id,exam_id) REFERENCES exams(center_id,id), FOREIGN KEY(center_id,subject_id) REFERENCES catalog(center_id,id));
INSERT INTO papers_new (id, center_id, exam_id, subject_id, maximum, position, version) SELECT id, center_id, exam_id, subject_id, maximum, position, version FROM papers;
DROP TRIGGER result_max_insert;
DROP TRIGGER result_max_update;
DROP TRIGGER result_participant;
DROP TRIGGER paper_max_update;
DROP TRIGGER paper_revision_insert;
DROP TRIGGER paper_revision_update;
DROP TABLE papers;
ALTER TABLE papers_new RENAME TO papers;
CREATE INDEX papers_exam ON papers(center_id,exam_id,position,id);
CREATE TRIGGER result_max_insert BEFORE INSERT ON results WHEN NEW.score>(SELECT maximum FROM papers WHERE center_id=NEW.center_id AND id=NEW.paper_id) BEGIN SELECT RAISE(ABORT,'MARK_EXCEEDS_MAX'); END;
CREATE TRIGGER result_max_update BEFORE UPDATE ON results WHEN NEW.score>(SELECT maximum FROM papers WHERE center_id=NEW.center_id AND id=NEW.paper_id) BEGIN SELECT RAISE(ABORT,'MARK_EXCEEDS_MAX'); END;
CREATE TRIGGER result_participant BEFORE INSERT ON results WHEN NOT EXISTS(SELECT 1 FROM participants p JOIN papers x ON x.center_id=p.center_id AND x.exam_id=p.exam_id WHERE x.id=NEW.paper_id AND p.center_id=NEW.center_id AND p.student_id=NEW.student_id) BEGIN SELECT RAISE(ABORT,'INVALID_PARTICIPANT'); END;
CREATE TRIGGER paper_max_update BEFORE UPDATE OF maximum ON papers WHEN EXISTS(SELECT 1 FROM results WHERE center_id=OLD.center_id AND paper_id=OLD.id AND score>NEW.maximum) BEGIN SELECT RAISE(ABORT,'MARK_EXCEEDS_MAX'); END;
CREATE TRIGGER paper_revision_insert AFTER INSERT ON papers BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER paper_revision_update AFTER UPDATE ON papers BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
PRAGMA defer_foreign_keys = OFF;
